+      color: #07101f;
+      text-decoration: none;
+      transform: translateY(-160%);
+      transition: transform 160ms ease;
+    }
+
+    .skip-link:focus {
+      transform: translateY(0);
+      outline: 3px solid #fff;
+      outline-offset: 3px;
+    }
+
+    main {
+      width: min(100%, 56rem);
+      margin: 0 auto;
+      padding: 5rem 1.25rem 4rem;
