+
+    .hero {
+      margin-bottom: 1.75rem;
+      padding: 1.5rem;
+      border: 1px solid var(--border);
+      border-radius: 1.5rem;
+      background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
+      box-shadow: var(--shadow);
+    }
+
+    h1 {
+      margin: 0 0 0.5rem;
+      font-size: clamp(2rem, 5vw, 3.5rem);
+      line-height: 1.05;
+      letter-spacing: -0.04em;
+    }
+
+    .intro {
+      margin: 0;
+      max-width: 44rem;
+      color: var(--muted);
+      font-size: 1.05rem;
+    }
+
+    .faq-list {
+      display: grid;
+      gap: 1rem;
+    }
+
+    .example {
+      border: 1px solid var(--border);
+      border-radius: 1.25rem;
+      background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
+      box-shadow: 0 12px 28px rgba(0, 0, 0, 0.25);
+      overflow: hidden;
+    }
+
+    .details {
+      display: block;
+    }
+
+    .details > summary {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 1rem;
+      padding: 1.15rem 1.25rem;
+      cursor: pointer;
+      list-style: none;
+      font-weight: 700;
+      font-size: 1.05rem;
+      color: var(--text);
+    }
+
+    .details > summary::-webkit-details-marker {
+      display: none;
+    }
+
+    .details > summary::after {
+      content: "+";
+      flex: none;
+      width: 2rem;
+      height: 2rem;
+      display: grid;
+      place-items: center;
+      border-radius: 999px;
+      border: 1px solid var(--border);
+      color: var(--accent-strong);
+      background: rgba(142, 181, 255, 0.08);
+      font-size: 1.2rem;
+      line-height: 1;
+      transition: transform 160ms ease, background-color 160ms ease;
+    }
+
+    .details[open] > summary {
+      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
+    }
+
+    .details[open] > summary::after {
+      content: "–";
+      transform: rotate(180deg);
+      background: rgba(197, 216, 255, 0.16);
+    }
+
+    .details > summary:hover {
+      background: rgba(255, 255, 255, 0.03);
+    }
+
+    .details > summary:focus-visible {
+      outline: 3px solid var(--accent-strong);
+      outline-offset: -3px;
+      border-radius: 1.25rem;
+    }
+
+    .details-content {
+      padding: 0.05rem 1.25rem 1.25rem;
+      color: var(--muted);
+    }
+
+    .details-content p {
+      margin: 0.75rem 0 0;
+    }
+
+    .details-content p:first-child {
+      margin-top: 0.9rem;
+    }
+
+    .details-content ul {
+      margin: 0.75rem 0 0;
+      padding-left: 1.25rem;
+    }
+
+    .details-content li + li {
+      margin-top: 0.35rem;
+    }
+
+    @media (max-width: 40rem) {
+      main {
+        padding-inline: 1rem;
+        padding-top: 4.5rem;
+      }
+
+      .hero,
+      .details > summary,
+      .details-content {
+        padding-left: 1rem;
+        padding-right: 1rem;
+      }
+    }
+
+    @media (forced-colors: active) {
+      :root {
+        --bg: Canvas;
+        --bg-elevated: Canvas;
+        --bg-card: Canvas;
+        --border: ButtonBorder;
+        --text: CanvasText;
+        --muted: CanvasText;
+        --accent: LinkText;
+        --accent-strong: ButtonText;
+      }
+
+      body,
+      .hero,
+      .example {
+        background: Canvas;
+        color: CanvasText;
+        box-shadow: none;
+      }
+
+      .skip-link,
+      .details > summary::after {
+        forced-color-adjust: auto;
+      }
+
+      .details > summary:focus-visible,
+      .skip-link:focus {
+        outline-color: Highlight;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <main id="main-content">
+    <section class="hero" aria-labelledby="faq-title">
+      <h1 id="faq-title">Frequently asked questions about cats</h1>
+      <p class="intro">A quick guide to common cat curiosities, from purring to whiskers and why your lap suddenly became a favorite seat.</p>
+    </section>
+
+    <section class="faq-list" aria-label="Cat FAQ">
+      <div class="example">
+        <details class="details">
+          <summary>Why do cats purr?</summary>
+          <div class="details-content">
+            <p>Cats purr when they feel relaxed, but they may also purr to soothe themselves, communicate with people, or settle in after stress.</p>
+          </div>
+        </details>
+      </div>
+
+      <div class="example">
+        <details class="details">
+          <summary>Do cats really need a lot of sleep?</summary>
+          <div class="details-content">
+            <p>Yes. Many cats sleep 12 to 16 hours a day, and some sleep even more. Short bursts of energy are usually followed by long naps.</p>
+          </div>
+        </details>
+      </div>
+
+      <div class="example">
+        <details class="details">
+          <summary>Why do cats knead with their paws?</summary>
+          <div class="details-content">
+            <p>Kneading is often a comfort behavior that starts in kittenhood. Adult cats may knead when they feel safe, content, or especially attached to you.</p>
+          </div>
+        </details>
+      </div>
+
+      <div class="example">
+        <details class="details">
+          <summary>What are whiskers for?</summary>
+          <div class="details-content">
+            <p>Whiskers help cats sense space, judge openings, and detect nearby movement. They are highly sensitive touch tools, not just facial decoration.</p>
+          </div>
+        </details>
+      </div>
+
+      <div class="example">
+        <details class="details">
+          <summary>Why do cats bring home toys or prey?</summary>
+          <div class="details-content">
+            <p>This can be hunting instinct, practice, or a form of sharing. Some cats treat their humans as members of the household they want to care for.</p>
+          </div>
+        </details>
+      </div>
+
+      <div class="example">
+        <details class="details">
+          <summary>How can I make a cat feel comfortable?</summary>
+          <div class="details-content">
+            <p>Give them space, predictable routines, clean litter, fresh water, and cozy places to hide. Let the cat choose when to approach and interact.</p>
+            <ul>
+              <li>Use calm voices and slow movements.</li>
+              <li>Provide scratching posts and vertical perches.</li>
+              <li>Respect boundaries when they walk away.</li>
+            </ul>
+          </div>
+        </details>
+      </div>
+    </section>
+  </main>
+</body>
+</html>
*** End Patch
